/**
 * Toast's states fixture in element form, with the React fixture's entry
 * names, so a contract's `when <state>` names the same entry in every shell. Each
 * entry is the markup a page writes, and what its script sets once the elements
 * are defined.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/toast.ts`. Never edit it by hand.
 */
import { TOAST_MAX_VISIBLE, listen, toast, type ComponentStates } from '@polymorph/elements'

import '../controls/Button'
import '../layout/Inline'
import './Toast'
import './ToastViewport'

export const states: ComponentStates = {
  component: 'Toast',
  entries: [
    {
      name: 'the viewport, with a pinned title, a description and an action',
      html: `<poly-toast title="Ticket archived" tone="success"></poly-toast>
<poly-toast title="Ticket created"></poly-toast>
<poly-toast title="Ticket assigned" description="Sent to the triage queue."></poly-toast>
<poly-toast-viewport></poly-toast-viewport>`,
      subject: 'poly-toast-viewport',
      setup: (find) => {
        const e0 = find('poly-toast', 0)
        e0.action = {
          label: 'Undo',
          onClick: () =>
            document.dispatchEvent(new CustomEvent('polymorph:fixturecall', { detail: 'onClick' })),
        }
        listen(e0, 'poly-dismiss', () =>
          document.dispatchEvent(new CustomEvent('polymorph:fixturecall', { detail: 'onDismiss' })),
        )
        e0.durationMs = Number.POSITIVE_INFINITY
        const e1 = find('poly-toast', 1)
        listen(e1, 'poly-dismiss', () =>
          document.dispatchEvent(new CustomEvent('polymorph:fixturecall', { detail: 'onDismiss' })),
        )
        e1.durationMs = Number.POSITIVE_INFINITY
        const e2 = find('poly-toast', 2)
        listen(e2, 'poly-dismiss', () =>
          document.dispatchEvent(new CustomEvent('polymorph:fixturecall', { detail: 'onDismiss' })),
        )
        e2.durationMs = Number.POSITIVE_INFINITY
      },
    },
    {
      name: 'every tone — the card is the same, the glyph is not',
      html: `<poly-inline gap="2" wrap>
  <poly-button variant="outline" tone="neutral" size="sm" label="neutral"></poly-button>
  <poly-button variant="outline" tone="neutral" size="sm" label="success"></poly-button>
  <poly-button variant="outline" tone="neutral" size="sm" label="danger"></poly-button>
  <poly-button variant="outline" tone="neutral" size="sm" label="warning"></poly-button>
  <poly-button variant="outline" tone="neutral" size="sm" label="info"></poly-button>
</poly-inline>`,
      setup: (find) => {
        const e0 = find('poly-button', 0)
        listen(e0, 'poly-click', () =>
          toast({
            title: 'Neutral',
            description: 'The tone speaks through the glyph and nothing else.',
            tone: 'neutral',
          }),
        )
        const e1 = find('poly-button', 1)
        listen(e1, 'poly-click', () =>
          toast({
            title: 'Success',
            description: 'The tone speaks through the glyph and nothing else.',
            tone: 'success',
          }),
        )
        const e2 = find('poly-button', 2)
        listen(e2, 'poly-click', () =>
          toast({
            title: 'Danger',
            description: 'The tone speaks through the glyph and nothing else.',
            tone: 'danger',
          }),
        )
        const e3 = find('poly-button', 3)
        listen(e3, 'poly-click', () =>
          toast({
            title: 'Warning',
            description: 'The tone speaks through the glyph and nothing else.',
            tone: 'warning',
          }),
        )
        const e4 = find('poly-button', 4)
        listen(e4, 'poly-click', () =>
          toast({
            title: 'Info',
            description: 'The tone speaks through the glyph and nothing else.',
            tone: 'info',
          }),
        )
      },
    },
    {
      name: 'with an action',
      html: `<poly-inline gap="2" wrap>
  <poly-button variant="outline" tone="neutral" size="sm" label="Archive a ticket"></poly-button>
  <poly-button variant="outline" tone="neutral" size="sm" label="Fail to delete one"></poly-button>
</poly-inline>`,
      setup: (find) => {
        const e0 = find('poly-button', 0)
        listen(e0, 'poly-click', () =>
          toast.success('Ticket archived', { action: { label: 'Undo', onClick: () => undefined } }),
        )
        const e1 = find('poly-button', 1)
        listen(e1, 'poly-click', () =>
          toast.danger('Could not delete', {
            description: 'The ticket is referenced by another.',
            action: { label: 'Retry', onClick: () => undefined },
          }),
        )
      },
    },
    {
      name: 'pinned — it waits to be dismissed',
      html: `<poly-inline gap="2" wrap>
  <poly-button variant="outline" tone="neutral" size="sm" label="Raise a pinned toast"></poly-button>
</poly-inline>`,
      setup: (find) => {
        const e0 = find('poly-button', 0)
        listen(e0, 'poly-click', () =>
          toast({
            title: 'Still working',
            description: 'This one has no timer.',
            durationMs: Number.POSITIVE_INFINITY,
          }),
        )
      },
    },
    {
      name: 'a promise — the loading face pinned, then the settled face, same card',
      html: `<poly-inline gap="2" wrap>
  <poly-button variant="outline" tone="neutral" size="sm" label="Archive, resolving"></poly-button>
  <poly-button variant="outline" tone="neutral" size="sm" label="Archive, failing"></poly-button>
</poly-inline>`,
      setup: (find) => {
        const e0 = find('poly-button', 0)
        listen(e0, 'poly-click', () =>
          toast.promise(new Promise((resolve) => setTimeout(resolve, 2500)), {
            loading: 'Archiving ticket…',
            success: 'Ticket archived',
            error: 'Could not archive',
          }),
        )
        const e1 = find('poly-button', 1)
        listen(e1, 'poly-click', () =>
          toast.promise(new Promise((_, reject) => setTimeout(reject, 2500)), {
            loading: 'Archiving ticket…',
            success: 'Ticket archived',
            error: { title: 'Could not archive', description: 'The queue is read-only.' },
          }),
        )
      },
    },
    {
      name: 'updated in place — a second call with the first’s id, one card',
      html: `<poly-inline gap="2" wrap>
  <poly-button variant="outline" tone="neutral" size="sm" label="Raise, then update it"></poly-button>
</poly-inline>`,
      setup: (find) => {
        const e0 = find('poly-button', 0)
        listen(e0, 'poly-click', () => {
          toast({
            id: 'update-demo',
            title: 'Exporting 0 of 3…',
            durationMs: Number.POSITIVE_INFINITY,
          })
          setTimeout(
            () =>
              toast({
                id: 'update-demo',
                title: 'Exporting 2 of 3…',
                durationMs: Number.POSITIVE_INFINITY,
              }),
            1200,
          )
          setTimeout(
            () => toast({ id: 'update-demo', title: 'Export ready', tone: 'success' }),
            2400,
          )
        })
      },
    },
    {
      name: 'a stack — the survivors glide into the gap',
      html: `<poly-inline gap="2" wrap>
  <poly-button variant="outline" tone="neutral" size="sm" label="Raise 4"></poly-button>
  <poly-button variant="outline" tone="neutral" size="sm" label="Raise more than it will keep"></poly-button>
  <poly-button variant="ghost" tone="danger" size="sm" label="Dismiss all"></poly-button>
</poly-inline>`,
      setup: (find) => {
        const e0 = find('poly-button', 0)
        listen(e0, 'poly-click', () => {
          for (let index = 1; index <= TOAST_MAX_VISIBLE; index += 1)
            toast({ title: `Toast ${index}`, durationMs: Number.POSITIVE_INFINITY })
        })
        const e1 = find('poly-button', 1)
        listen(e1, 'poly-click', () => {
          for (let index = 1; index <= TOAST_MAX_VISIBLE + 3; index += 1)
            toast({ title: `Overflow ${index}` })
        })
        const e2 = find('poly-button', 2)
        listen(e2, 'poly-click', () => toast.dismiss())
      },
    },
  ],
}
